/**
 * Budget item lifespans. An item is active on the local days
 * `[startsOn, retiredOn)`: its start date is its first day, its retirement date
 * (exclusive) the first day it no longer applies. Dates are ISO `YYYY-MM-DD` in
 * the household's timezone, compared as strings.
 */

/** The timezone a household's local days are read in when no other is known. */
export const HOUSEHOLD_TIME_ZONE = 'Australia/Sydney'

/** An item's lifespan; either side open when null or absent. */
export interface Lifespan {
  /** The first local day the item applies. */
  readonly startsOn?: string | null
  /** The first local day the item no longer applies (exclusive). */
  readonly retiredOn?: string | null
}

/** Whether an item with `lifespan` is active on the local day `today`. */
export function isBudgetLineActive(lifespan: Lifespan, today: string): boolean {
  return (
    (lifespan.startsOn == null || lifespan.startsOn <= today) &&
    (lifespan.retiredOn == null || today < lifespan.retiredOn)
  )
}

/** Whether an item has retired by the local day `today`. */
export function isBudgetLineRetired(lifespan: Lifespan, today: string): boolean {
  return lifespan.retiredOn != null && lifespan.retiredOn <= today
}

/** The local day (ISO `YYYY-MM-DD`) `now` falls on in `timeZone`. */
export function localIsoDate(now: Date, timeZone: string = HOUSEHOLD_TIME_ZONE): string {
  return now.toLocaleDateString('en-CA', { timeZone })
}
